  _waTime(value) {
    if (!value) return "";
    const date = parseDate(value);
    if (!date) return "";
    return ymd(date) === todayStr() ? timeOf(date) : `${pad(date.getDate())}/${pad(date.getMonth() + 1)}`;
  }

  /** "+39 340 555 1212" from "393405551212@c.us". */
  _chatLabel(chatId) {
    const digits = String(chatId || "").split("@")[0].replace(/\D/g, "");
    if (!digits) return String(chatId || "");
    const { cc, number } = splitPhone(`+${digits}`);
    return `+${cc} ${number}`;
  }

  /** The client whose phone is this WhatsApp chat, if any. */
  _clientByChat(chatId) {
    const digits = String(chatId || "").split("@")[0].replace(/\D/g, "");
    if (!digits) return null;
    return (this._data.clients || []).find((client) => {
      if (!client.phone) return false;
      const { cc, number } = splitPhone(client.phone);
      return `${cc}${number.replace(/\D/g, "")}` === digits;
    }) || null;
  }

  /** "4 visite · prossimo gio 12 alle 11:30". */
  _clientSummary(client) {
    const now = new Date();
    const mine = (this._data.appointments || []).filter((a) => a.client_id === client.id && a.status !== "cancelled");
    const next = mine
      .map((a) => ({ a, start: parseDate(a.start) }))
      .filter(({ start }) => start && start > now)
      .sort((x, y) => x.start - y.start)[0];
    const visits = mine.filter((a) => { const start = parseDate(a.start); return start && start <= now; }).length;
    const bits = [`Cliente · ${visits} ${visits === 1 ? "visita" : "visite"}`];
    if (next) bits.push(`prossimo ${longDay(next.start).split(" ").slice(0, 2).join(" ")} alle ${timeOf(next.start)}`);
    return bits.join(" · ");
  }

  _replyToWhatsapp(chatId, originalText) {
    // Toggle an inline reply form for this chat
    if (this._waReplyTo === chatId) {
      this._waReplyTo = null;
      this._render();
      return;
    }
    this._waReplyTo = chatId;
    this._waReplyText = "";
    this._render();
  }

  _sendWaReply(chatId) {
    const text = (this._waReplyText || "").trim();
    if (!text) return;
    this._waBusy = true;
    this._call("send_external_message", { chat_id: chatId, text }).then(() => {
      // The server keeps the reply in the conversation (2.3.5).
      this._refreshWaChats(true);
      this._waReplyTo = null;
      this._waReplyText = "";
      this._waBusy = false;
      this._message = { kind: "ok", text: "Risposta inviata." };
      this._render();
    }).catch(() => {
      this._waBusy = false;
      this._message = { kind: "error", text: "Invio fallito." };
      this._render();
    });
  }

  _createRequestFromWhatsapp(chatId) {
    const phone = this._phoneFromChat(chatId);
    // The request form reads this._form, not this._draft: write the number
    // there and open it as a new client, so the phone field is the one shown.
    this._form = { ...this._form, phone, client_mode: "new" };
    this._tab = "nuovo";
    this._nuovoTab = "nuova";
    this._waReplyTo = null;
    this._waReplyText = "";
    this._render();
  }

  /**
   * The phone number of a WhatsApp chat id, written with its "+".
   *
   * A chat id (393331234567@c.us) already carries the full international
   * number. The old code put "39" in front of anything not starting with 39,
   * so a Swiss or German guest became a wrong Italian number. The "+" keeps
   * the server from guessing the country again. A @lid or a group id is not
   * a phone number: nothing is filled in.
   */
  _phoneFromChat(chatId) {
    const raw = String(chatId || "").replace(/\s+/g, "");
    const [user, server] = raw.includes("@") ? raw.split("@") : [raw, "c.us"];
    if (server && server !== "c.us" && server !== "s.whatsapp.net") return "";
    const digits = user.replace(/\D/g, "");
    return digits ? `+${digits}` : "";
  }

  _saveAsClient(chatId) {
    const phone = this._phoneFromChat(chatId);
    if (!phone) {
      this._message = { kind: "error", text: "Questa chat non ha un numero di telefono da salvare." };
      this._render();
      return;
    }
    if (!this._draft) this._draft = {};
    this._call("save_client", {
      first_name: "Esterno",
      last_name: "",
      phone: phone,
      category_id: "external",
      client_notes: "Numero esterno WhatsApp - salvato da card",
    }).then(() => {
      this._message = { kind: "ok", text: "Salvato come cliente esterno." };
      this._render();
    }).catch(() => {
      this._message = { kind: "error", text: "Salvataggio fallito." };
    });
  }

  /** How many requests arrived from the website and nobody has opened yet. */
  _webUnreadCount() {
    const list = (this._data && this._data.requests) || [];
    return list.filter((req) => req.source === "web" && !req.seen).length;
  }

  /** Open the request list and consider the website's requests seen. */
  async _openWebRequests() {
    this._tab = "nuovo";
    this._nuovoTab = "lista";
    this._render();
    try {
      await this._service("mark_requests_seen", {});
      await this._loadData();
    } catch (error) {
      /* the badge stays where it was; the next click retries */
    }
    this._render();
  }

