    /** Load a request into the form for editing. */
  _editRequest(req) {
    const people = Math.max(1, Number(req.people) || 1);
    const entries = req.entries || [];
    const toTreat = (e) => ({
      ...this._blankTreatment(),
      treatment_id: e.treatment_id,
      time: e.time || "10:00",
      // Kept so «Modifica» does not lose a person's wish from the website.
      ...(e.therapist_preference ? { therapist_preference: e.therapist_preference } : {}),
    });
    // Entries that name their person (website, or saved from 2.1.1 on) go
    // in her box; older entries were meant for everybody, so each box gets
    // them all — what is on screen is exactly what confirming would book.
    const tagged = entries.some((e) => e.person !== undefined && e.person !== null);
    let persons = null;
    let treatments = entries.map(toTreat);
    let extras = entries.length ? [...(entries[0].extras || [])] : [];
    if (people > 1) {
      persons = Array.from({ length: people }, (_, index) => {
        const mine = tagged ? entries.filter((e) => (Number(e.person) || 0) === index) : entries;
        return this._personFrom({
          treatments: mine.length ? mine.map(toTreat) : [this._blankTreatment()],
          extras: mine.length ? [...(mine[0].extras || [])] : [],
        });
      });
      treatments = [];
      extras = [];
    }
    this._form = {
      ...this._form,
      request_id: req.id,
      date: req.date,
      people,
      persons,
      treatments,
      extras,
      client_mode: req.client_id ? "existing" : "new",
      client_id: req.client_id || "",
      first_name: req.client?.first_name || "",
      last_name: req.client?.last_name || "",
      phone: req.client?.phone || "",
      email: req.client?.email || "",
      client_notes: req.client?.client_notes || "",
      notes: req.notes || "",
      voucher_code: req.voucher_code || "",
      guest_type: req.guest_type || GUEST_DEFAULT,
      therapist_preference: req.therapist_preference || "",
      partner_id: req.partner_id || "",
      new_client: false,
    };
    this._tab = "nuovo";
    this._nuovoTab = "nuova";
    this._render();
  }

  /** Clienti with two sub-tabs (2.4.0): the clients and the partners. */
  _renderClients() {
    const tab = this._clientsTab || "clienti";
    const wrap = el("div", { class: "stack" });
    const partners = (this._data.partners || []).length;
    wrap.appendChild(el("div", { class: "nt-tabs", role: "tablist" },
      [["clienti", "mdi:account-multiple-outline", `Clienti (${(this._data.clients || []).length})`],
        ["partner", "mdi:handshake-outline", `Partner (${partners})`]]
        .map(([id, icon, label]) => el("button", {
          class: `nt-tab${tab === id ? " on" : ""}`, role: "tab", "aria-selected": tab === id ? "true" : "false",
          on: { click: () => { this._clientsTab = id; this._render(); } },
        }, el("ha-icon", { icon }), el("span", {}, label)))));
    add(wrap, tab === "partner" ? this._renderPartners() : this._renderClientsList());
    return wrap;
  }

  /** The VAT rate of a treatment: its own, else the default (2.5.1). */
  _vatOfTreatment(treatment) {
    if (treatment && treatment.vat_rate != null) return Number(treatment.vat_rate);
    return Number(((this._data && this._data.settings) || {}).vat_default ?? 22);
  }

  /** The VAT rate of a booking: frozen at booking time, else the treatment's. */
  _vatOfAppointment(appointment) {
    if (appointment && appointment.vat_rate != null) return Number(appointment.vat_rate);
    return this._vatOfTreatment(this._lookup.treatment.get(appointment && appointment.treatment_id));
  }

  /** «di cui IVA» lines, grouped by rate: [[rate, taxable, vat], …]. */
  _vatLines(items) {
    const byRate = new Map();
    items.forEach(([gross, rate]) => {
      const split = vatSplit(gross, rate);
      const row = byRate.get(rate) || [0, 0];
      byRate.set(rate, [row[0] + split.taxable, row[1] + split.vat]);
    });
    return [...byRate.entries()].sort((a, b) => b[0] - a[0])
      .map(([rate, [taxable, vat]]) => [rate, Math.round(taxable * 100) / 100, Math.round(vat * 100) / 100]);
  }

